if ($period === null || ! $period->isArchived()) {
    $blockers[] = 'It has not been archived.';
}

if ($years === null || $cutoff === null) {
    // Unset means nobody has decided how long documents are kept.
    // Reading that as "keep nothing" would make an instance that was
    // never configured the one that deletes.
    $blockers[] = 'No retention window is configured.';
} elseif ($period?->archived_at !== null && $period->archived_at->greaterThan($cutoff)) {
    // Measured from archived_at rather than from the end of the
    // period: that is when the operator declared it closed, and it is
    // always the later of the two, so it is the safer clock.
    $blockers[] = sprintf(
        'It is inside the %d-year retention window until %s.',
        (int) $years,
        $period->archived_at->addYears((int) $years)->toDateString(),
    );
}

if ($held > 0) {
    // The whole period stays, not merely the held files: a partial
    // purge of a period under legal hold is exactly what a hold
    // exists to prevent.
    $blockers[] = sprintf('%d file(s) are under legal hold.', $held);
}

->when($trashedPaths !== [], function (Builder $query) use ($trashedPaths): void {
    foreach ($trashedPaths as $trashedPath) {
        $query->where('path', 'not like', $trashedPath.'%');
    }
})

if ($directory === null) {
    // A trashed directory is already invisible to browsing and
    // search (DirectoryAccess::resolveViewable()); viewing a file
    // inside it one at a time must not become a side door around
    // that. See the class docblock.
    return false;
}

if ($directory === null) {
    // Editing metadata in place on a file inside a trashed subtree
    // is the same reveal-and-modify that view() refuses. See the
    // class docblock.
    return false;
}

if ($directory === null) {
    // move() assumes a live file in a live tree, the same as
    // view() and update(); restoring it out of a trashed subtree is
    // restore()'s job, done before a move rather than instead of
    // one. See the class docblock.
    return false;
}

if ($directory === null) {
    // Resolving withTrashed() here would turn the hold check itself
    // into the side channel the view-reach requirement above exists
    // to close: a trashed directory is hidden from view precisely
    // so a capability holder cannot learn what is in it, and legal
    // hold must not carve out an exception to that. See the class
    // docblock.
    return false;
}
